CustomField.formula:
/* If This Record is GUD-Level Then use Name field from this Record itself */ 
If (TEXT( IM_Hierarchy_Level__c )=='Country Parent' , Name, 

/* Else If No Parent AND This Record is NOT GUD-Level Then use BLANK*/ 
If(LEN(ParentId)==0 && TEXT( IM_Hierarchy_Level__c )!='Country Parent' , '', 

/*Else If immediate parent is GUD-Level, get Name from parent*/ 
If (TEXT( Parent.IM_Hierarchy_Level__c )=='Country Parent' , Parent.Name, 


/*Else If second parent is GUD-Level, get Name from parent*/ 
If (TEXT( Parent.Parent.IM_Hierarchy_Level__c )=='Country Parent' , Parent.Parent.Name, 

/*Else If third parent is GUD-Level, get Name from parent*/ 
If (TEXT( Parent.Parent.Parent.IM_Hierarchy_Level__c )=='Country Parent' , Parent.Parent.Parent.Name, 

/*Else If fourth parent is GUD-Level, get Name from parent*/ 
If (TEXT( Parent.Parent.Parent.Parent.IM_Hierarchy_Level__c )=='Country Parent' , 
Parent.Parent.Parent.Parent.Name, 
/*Else If fifth parent is GUD-Level, get Name from parent*/ 
If (TEXT( Parent.Parent.Parent.Parent.Parent.IM_Hierarchy_Level__c )=='Country Parent' , 
Parent.Parent.Parent.Parent.Parent.Name, 

/*Else (when reached up five levels, if no GUD-level parent found - then put blank.*/ 
'' )))))))
